package com.wetech.demo.web3j.contracts.escrow;

import org.web3j.protocol.core.RemoteCall;
import org.web3j.abi.FunctionEncoder;
import java.math.BigInteger;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import org.web3j.abi.EventEncoder;
import org.web3j.abi.TypeReference;
import org.web3j.abi.datatypes.Address;
import org.web3j.abi.datatypes.Event;
import org.web3j.abi.datatypes.Function;
import org.web3j.abi.datatypes.Type;
import org.web3j.abi.datatypes.Utf8String;
import org.web3j.abi.datatypes.generated.Uint256;
import org.web3j.abi.datatypes.generated.Uint8;
import org.web3j.crypto.Credentials;
import org.web3j.protocol.Web3j;
import org.web3j.protocol.core.RemoteFunctionCall;
import org.web3j.protocol.core.methods.response.Log;
import org.web3j.protocol.core.methods.response.TransactionReceipt;
import org.web3j.tx.Contract;
import org.web3j.tx.TransactionManager;
import org.web3j.tx.gas.ContractGasProvider;

@SuppressWarnings("rawtypes")
public class Escrow extends Contract {
    public static final String BINARY = "";
    //因 WSL 下 Web3j 4.14.0 插件生成报错，改为从 Remix 手动复制 BINARY

    public static final String FUNC_GETORDER = "getOrder";
    public static final String FUNC_CREATEORDER = "createOrder";
    public static final String FUNC_DEPOSIT = "deposit";
    public static final String FUNC_CONFIRM = "confirm";
    public static final String FUNC_REFUND = "refund";
    public static final String FUNC_DISPUTE = "dispute";
    public static final String FUNC_RESOLVE = "resolve";
    public static final String FUNC_ARBITER = "arbiter";
    public static final String FUNC_ORDERCOUNT = "orderCount";


    public static final Event ORDERCREATED_EVENT = new Event("OrderCreated",
            Arrays.<TypeReference<?>>asList(
                    new TypeReference<Uint256>(true) {},
                    new TypeReference<Address>(true) {},
                    new TypeReference<Address>(true) {},
                    new TypeReference<Address>() {},
                    new TypeReference<Uint256>() {},
                    new TypeReference<Uint256>() {}
            ));

    protected Escrow(String contractAddress, Web3j web3j, Credentials credentials, ContractGasProvider contractGasProvider) {
        super(BINARY, contractAddress, web3j, credentials, contractGasProvider);
    }

    protected Escrow(String contractAddress, Web3j web3j, TransactionManager transactionManager, ContractGasProvider contractGasProvider) {
        super(BINARY, contractAddress, web3j, transactionManager, contractGasProvider);
    }

    public RemoteFunctionCall<String> arbiter() {
        final Function function = new Function(FUNC_ARBITER, Arrays.<Type>asList(), Arrays.<TypeReference<?>>asList(new TypeReference<Address>() {}));
        return executeRemoteCallSingleValueReturn(function, String.class);
    }

    public RemoteFunctionCall<BigInteger> orderCount() {
        final Function function = new Function(FUNC_ORDERCOUNT, Arrays.<Type>asList(), Arrays.<TypeReference<?>>asList(new TypeReference<Uint256>() {}));
        return executeRemoteCallSingleValueReturn(function, BigInteger.class);
    }

    public RemoteFunctionCall<TransactionReceipt> createOrder(String seller, String token, BigInteger amount, BigInteger deadline, String description) {
        final Function function = new Function(FUNC_CREATEORDER, Arrays.<Type>asList(new Address(seller), new Address(token), new Uint256(amount), new Uint256(deadline), new Utf8String(description)), Collections.<TypeReference<?>>emptyList());
        return executeRemoteCallTransaction(function);
    }

    public RemoteFunctionCall<TransactionReceipt> deposit(BigInteger id) {
        final Function function = new Function(FUNC_DEPOSIT, Arrays.<Type>asList(new Uint256(id)), Collections.<TypeReference<?>>emptyList());
        return executeRemoteCallTransaction(function);
    }

    public RemoteFunctionCall<TransactionReceipt> confirm(BigInteger id) {
        final Function function = new Function(FUNC_CONFIRM, Arrays.<Type>asList(new Uint256(id)), Collections.<TypeReference<?>>emptyList());
        return executeRemoteCallTransaction(function);
    }

    public RemoteFunctionCall<TransactionReceipt> dispute(BigInteger id) {
        final Function function = new Function(FUNC_DISPUTE, Arrays.<Type>asList(new Uint256(id)), Collections.<TypeReference<?>>emptyList());
        return executeRemoteCallTransaction(function);
    }

    public RemoteFunctionCall<TransactionReceipt> resolve(BigInteger id, Boolean sellerWins) {
        final Function function = new Function(FUNC_RESOLVE, Arrays.<Type>asList(new Uint256(id), new org.web3j.abi.datatypes.Bool(sellerWins)), Collections.<TypeReference<?>>emptyList());
        return executeRemoteCallTransaction(function);
    }

    public RemoteFunctionCall<Order> getOrder(BigInteger id) {
        final Function function = new Function(FUNC_GETORDER, Arrays.<Type>asList(new Uint256(id)), Arrays.<TypeReference<?>>asList(
                new TypeReference<Address>() {},
                new TypeReference<Address>() {},
                new TypeReference<Address>() {},
                new TypeReference<Uint256>() {},
                new TypeReference<Uint256>() {},
                new TypeReference<Uint8>() {},
                new TypeReference<Utf8String>() {}
        ));
        return new RemoteFunctionCall<>(function, () -> {
            List<Type> result = executeCallMultipleValueReturn(function);
            return new Order(
                    (String) result.get(0).getValue(),
                    (String) result.get(1).getValue(),
                    (String) result.get(2).getValue(),
                    (BigInteger) result.get(3).getValue(),
                    (BigInteger) result.get(4).getValue(),
                    (BigInteger) result.get(5).getValue(),
                    (String) result.get(6).getValue()
            );
        });
    }

    public List<OrderCreatedEventResponse> getOrderCreatedEvents(TransactionReceipt transactionReceipt) {
        List<OrderCreatedEventResponse> responses = new ArrayList<>();
        for (Log log : transactionReceipt.getLogs()) {
            if (log.getTopics().get(0).equals(EventEncoder.encode(ORDERCREATED_EVENT))) {
                EventValuesWithLog eventValues = staticExtractEventParametersWithLog(ORDERCREATED_EVENT, log);
                responses.add(new OrderCreatedEventResponse(eventValues));
            }
        }
        return responses;
    }

    public static OrderCreatedEventResponse getOrderCreatedEventFromLog(Log log) {
        EventValuesWithLog eventValues = staticExtractEventParametersWithLog(ORDERCREATED_EVENT, log);
        return new OrderCreatedEventResponse(eventValues);
    }

    public static class Order {
        public String buyer;
        public String seller;
        public String token;
        public BigInteger amount;
        public BigInteger deadline;
        public BigInteger status;
        public String description;

        public Order(String buyer, String seller, String token, BigInteger amount, BigInteger deadline, BigInteger status, String description) {
            this.buyer = buyer;
            this.seller = seller;
            this.token = token;
            this.amount = amount;
            this.deadline = deadline;
            this.status = status;
            this.description = description;
        }
    }

    public static class OrderCreatedEventResponse {
        public BigInteger id;
        public String buyer;
        public String seller;
        public String token;
        public BigInteger amount;
        public BigInteger deadline;

        public OrderCreatedEventResponse(EventValuesWithLog eventValues) {
            this.id = (BigInteger) eventValues.getIndexedValues().get(0).getValue();
            this.buyer = (String) eventValues.getIndexedValues().get(1).getValue();
            this.seller = (String) eventValues.getIndexedValues().get(2).getValue();
            this.token = (String) eventValues.getNonIndexedValues().get(0).getValue();
            this.amount = (BigInteger) eventValues.getNonIndexedValues().get(1).getValue();
            this.deadline = (BigInteger) eventValues.getNonIndexedValues().get(2).getValue();
        }
    }

    // 部署方法
    public static RemoteCall<Escrow> deploy(Web3j web3j, Credentials credentials, ContractGasProvider contractGasProvider, String _arbiter) {
        String encodedConstructor = FunctionEncoder.encodeConstructor(Arrays.<Type>asList(new org.web3j.abi.datatypes.Address(_arbiter)));
        return deployRemoteCall(Escrow.class, web3j, credentials, contractGasProvider, BINARY, encodedConstructor);
    }

    public static Escrow load(String contractAddress, Web3j web3j, Credentials credentials, ContractGasProvider contractGasProvider) {
        return new Escrow(contractAddress, web3j, credentials, contractGasProvider);
    }

    public static Escrow load(String contractAddress, Web3j web3j, TransactionManager transactionManager, ContractGasProvider contractGasProvider) {
        return new Escrow(contractAddress, web3j, transactionManager, contractGasProvider);
    }
}